import{z as i,x as s,o as r,c as d,q as A,j as B,D as t,d as e,s as o,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"quoted 曲线的维护","description":"","frontmatter":{"title":"quoted 曲线的维护","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/omm-curve-maintenance.md","filePath":"quant/omm-curve-maintenance.md","lastUpdated":1791413859000}'),u={name:"quant/omm-curve-maintenance.md"};function m(p,a,h,D,q,c){const n=s("Mermaid");return r(),d("div",null,[a[2]||(a[2]=A('<h1 id="quoted-曲线的维护" tabindex="-1">quoted 曲线的维护 <a class="header-anchor" href="#quoted-曲线的维护" aria-label="Permalink to &quot;quoted 曲线的维护&quot;">​</a></h1><div class="epigraph"><p>做市商不报整条曲面，报的是参数；维护曲线不是拟合科学，是给自家报价装一套有审计轨迹的过滤器。</p><footer>—— 据 Gatheral, The Volatility Surface 曲面参数化各章；报价维护流程据做市实务整理</footer></div><p><a href="/quant/omm-greeks-limits">上一课</a>把敏感度折成情景限额，闸门装好了。闸门之外，报价是把市场曲面翻译成自家买卖价的一层：做市台不逐点盯几千个执行价，而是维护参数化切片，从参数导出每档报价。本课写 quoted 曲线的日常维护：输入、过滤、拟合、无套利检查、加价与库存偏移，以及快市里「加宽」与「撤单」的取舍。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>原始输入是脏的：经纪商报价有单边、有陈旧、有错误；自家成交集中在少数执行价，翼部几天无成交。直接在原始点上插值，一个错价会顺着插值核污染整段执行价；把拟合当回归科学，参数跟着噪声抖动，报价全表重绘。缺的是一条受控管线：从噪声输入到稳定的报价参数，每一步可审计。</p><p>第二个缺口是口径：市场曲面与 quoted 曲线不是同一个对象。前者是市场共识的估计，后者叠加了自家库存方向、限额余量与 <a href="/quant/inventory-skew">存货偏移</a>——同一张 <a href="/quant/svi-ssvi">SVI</a> 切片，两个台报出的中心与宽度可以不同，且都应该不同。</p><p><span class="marginnote">术语翻译：市场曲面是「全市场对波动率水平的共识估计」，quoted 曲线则是做市商在这套共识之上、叠加自家库存方向与限额余量后实际报出去的价。可以类比批发行情与零售标价：后者在成本之外，还要看你自家仓库想不想出货。</span></p><h3 id="管线四段" tabindex="-1">管线四段 <a class="header-anchor" href="#管线四段" aria-label="Permalink to &quot;管线四段&quot;">​</a></h3><p><strong>输入段</strong>：自家成交（最可信，因为真的成交了）、双边经纪商报价、交易所盘口，每条带时间戳与可信度权重。<a href="/quant/omm-book-layering">手层账本</a> 在这里再次发挥作用：成交隐波直接进入拟合，带着批次标签可回溯。<strong>过滤段</strong>：单边价折价、陈旧价按到期桶设 TTL、离群价按与当前切片的距离剔除。<strong>拟合段</strong>：按到期拟合 SVI 切片或直接更新 <a href="/quant/ssvi-term-consistency">SSVI</a> 骨架，正则化约束相邻两期参数的跳变，见 <a href="/quant/svi-arb-params">无套利参数化</a>；拟合残差超阈值时宁可部分失效也不硬拟。<strong>发布段</strong>：从参数加半价差生成报价，价差按 Delta 带与剩余时间查表，再加库存偏移与限额状态调整。</p><p><span class="marginnote">TTL 要分桶设：当周切片几秒就陈旧，两年期切片可以撑几小时。用单一 TTL 要么让远期曲线无谓重绘，要么让近端报价挂在昨天的市场上——后者是做市商亏损的经典来源。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>更新节奏与现货绑定：现货一个有效 tick 未动，曲线不必重拟，只重算贴值档的绝对价格；现货动了，先重排贴值区，再决定是否重拟。<a href="/quant/butterfly-calendar-arb">蝶式、日历扫描</a> 每次都跑：自家成交落在切片上，等于一次免费校准点；扫描发现违例，回写参数而不是改报价。快市的规则事先写死：波动超过阈值时价差查表自动加宽，限级再升时收缩报价范围（只报核心 Delta 带），最内层才允许整片撤单——撤单是有义务约束的台子的最后手段。</p><p><span class="marginnote">数字实例：标的现价 100，按 Delta 带查表得半价差 0.5，报价即买 99.5、卖 100.5；若库存偏多、中心整体下移 0.2，就变成买 99.3、卖 100.3——买价更早被打到，成交更偏「客户把你手里的货买走」，库存风险随之回落。</span></p>',13)),(r(),B(l,null,{default:t(()=>[o(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E8%87%AA%E5%AE%B6%E6%88%90%E4%BA%A4%22%5D%20--%3E%20B%5B%22%E8%BF%87%E6%BB%A4%E6%AE%B5%20%E5%8D%95%E8%BE%B9%20%E9%99%88%E6%97%A7%20%E7%A6%BB%E7%BE%A4%22%5D%0A%20%20C%5B%22%E7%BB%8F%E7%BA%AA%E5%95%86%E6%8A%A5%E4%BB%B7%22%5D%20--%3E%20B%0A%20%20D%5B%22%E4%BA%A4%E6%98%93%E6%89%80%E7%9B%98%E5%8F%A3%22%5D%20--%3E%20B%0A%20%20B%20--%3E%20E%5B%22%E6%8B%9F%E5%90%88%E6%AE%B5%20SVI%2FSSVI%20%E5%8A%A0%E6%AD%A3%E5%88%99%22%5D%0A%20%20E%20--%3E%20F%5B%22%E6%97%A0%E5%A5%97%E5%88%A9%E6%89%AB%E6%8F%8F%20%E8%9D%B6%E5%BC%8F%20%E6%97%A5%E5%8E%86%22%5D%0A%20%20F%20--%3E%7C%E8%BF%9D%E4%BE%8B%7C%20E%0A%20%20F%20--%3E%20G%5B%22%E5%8F%91%E5%B8%83%E6%AE%B5%20%E5%8D%8A%E4%BB%B7%E5%B7%AE%20%E5%8A%A0%E5%BA%93%E5%AD%98%E5%81%8F%E7%A7%BB%22%5D%0A%20%20G%20--%3E%20H%5B%22%E5%AE%A2%E6%88%B7%E6%88%90%E4%BA%A4%20%E5%9B%9E%E5%86%99%E8%BE%93%E5%85%A5%E6%AE%B5%22%5D%0A%20%20H%20--%3E%20A%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("管线必须是单向回路：报价发布后，成交是最硬的新信息，绕过成交直接信经纪商，等于让别人的仓位替自己的库存说话。正则化不可省：相邻期限的参数跳变会被 "),E("a",{href:"/quant/butterfly-calendar-arb"},"日历检查"),e(" 抓住，但抓住之前报价已经互相打架，先内后外平仓的客户端可以两头吃。库存偏移的机制来自存货理论：库存偏多的台下移中心、让买价更积极，"),E("a",{href:"/quant/avellaneda-stoikov"},"Avellaneda–Stoikov"),e(" 把它写成库存的指数效用，quoted 曲线是同一机制的执行层。")],-1)),a[5]||(a[5]=E("p",null,"不这么做会错在哪：没有过滤段，一个 99 的单边报价能把整段翼部拉上去，对手用你的报价对冲自己的库存，你收下一袋子没人要的翼部；没有发布段与输入段的回路，曲线永远在追赶市场而不是引导成交。",-1)),(r(),B(l,null,{default:t(()=>[o(n,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%B8%82%E5%9C%BA%E6%B3%A2%E5%8A%A8%E5%8D%87%E7%BA%A7%22%5D%20--%3E%20B%7B%22%E8%B6%85%E8%BF%87%E5%8A%A0%E5%AE%BD%E9%98%88%E5%80%BC%3F%22%7D%0A%20%20B%20--%3E%7C%22%E5%90%A6%22%7C%20Z%5B%22%E7%BB%B4%E6%8C%81%E5%8E%9F%E6%8A%A5%E4%BB%B7%E4%B8%8E%E4%BB%B7%E5%B7%AE%22%5D%0A%20%20B%20--%3E%7C%22%E6%98%AF%22%7C%20C%5B%22%E4%BB%B7%E5%B7%AE%E6%9F%A5%E8%A1%A8%E8%87%AA%E5%8A%A8%E5%8A%A0%E5%AE%BD%22%5D%0A%20%20C%20--%3E%20D%7B%22%E9%99%90%E7%BA%A7%E7%BB%A7%E7%BB%AD%E4%B8%8A%E5%8D%87%3F%22%7D%0A%20%20D%20--%3E%7C%22%E5%90%A6%22%7C%20E%5B%22%E6%94%B6%E7%BC%A9%E5%88%B0%E6%A0%B8%E5%BF%83%20Delta%20%E5%B8%A6%22%5D%0A%20%20D%20--%3E%7C%22%E6%98%AF%22%7C%20F%5B%22%E6%95%B4%E7%89%87%E6%92%A4%E5%8D%95%20%E6%9C%80%E5%90%8E%E6%89%8B%E6%AE%B5%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=A('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>quoted 曲线只对自己负责：它不是市场共识，不能直接当盯市价用——盯市要回到市场口径与独立的仲裁规则。义务做市的品种，报价范围与响应时间受协议约束，加宽与撤单的自由度比自营台小。翼部流动性差的切片，报价宽度主要由对冲成本与尾部限额决定，而不是拟合优度。最后，维护是跨时段问题：夜盘与跨所标的的曲线接力，TTL 与触发阈值要按时段配置，别把「一天」当成常数。</p><p><span class="marginnote">常见误区：初学者容易以为快市里做市商「撤得越快越安全」。实际上对负有报务义务的台，频繁整片撤单会触发协议处罚、丢掉客户流；正确的次序是先加宽、再缩范围，撤单永远排在最后——它是压舱石，不是第一步。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>quoted 曲线是市场曲面加库存与限额的受控投影，与市场共识是两个对象。</li><li>管线四段：输入带权重、过滤带 TTL、拟合带正则、发布带偏移；每步可审计。</li><li>自家成交是最硬的校准点，必须回写输入段形成闭环。</li><li>快市规则事先写死：加宽、缩范围、撤单，三档依次使用。</li><li>quoted 价不当盯市价；义务做市约束报价自由度。</li><li>出处：据 Gatheral, <em>The Volatility Surface</em>；管线与偏移实务据期权做市运营整理。</li></ul>',5))])}const C=i(u,[["render",m]]);export{T as __pageData,C as default};
